mapper.select:
SELECT SVA.ID, SVS.VEHICLE_ID, SP.PARK_NAME, SS. NAME, SS.DEP_NAME, SVA.STATUS AS APPLY_STATUS, SVA.CREATE_TIME, SV.VEHICLE_PLATE, SS.PHONE, SS.WELFARE_LEVEL FROM SMT_VEHICLE_APPLY SVA LEFT JOIN SMT_VEHICLE SV ON SV. ID = SVA.VEHICLE_ID LEFT JOIN SMT_VEHICLE_STAFF SVS ON SV. ID = SVS.VEHICLE_ID INNER JOIN SMT_STAFF SS ON SVS.STAFF_ID = SS. ID LEFT JOIN SMT_PARK SP ON SVA.PARK_ID = SP. ID
AND SV.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND SVA.PARK_ID = #{query.parkId}
AND SVA.PARK_ID IN
#{tempId}
AND SVA.STATUS = #{query.status}
AND TO_DATE(TO_CHAR(SVA.CREATE_TIME, 'YYYY-MM-DD'),'YYYY-MM-DD') >= TO_DATE(#{query.startTime}, 'yyyy-MM-dd')
AND TO_DATE(TO_CHAR(SVA.CREATE_TIME, 'YYYY-MM-DD'),'YYYY-MM-DD') <= TO_DATE(#{query.endTime}, 'yyyy-MM-dd')
ORDER BY SVA.CREATE_TIME DESC
